102	    /**
103	     * 整体替换草稿占用清单，版本加一；仅 DRAFT 可改，expectedVersion 必须匹配。
104	     */
105	    public PlanResponse replaceOccupancies(String scheduleKey, UpdateOccupanciesRequest req) {
106	        validateOccupancyParams(req.occupancies());
107	        String hash = hashUpdate(scheduleKey, req);
108	        Optional<PlanResponse> replay = replayIfPresent(OP_UPDATE, req.requestKey(), hash);
109	        if (replay.isPresent()) {
110	            return replay.get();
111	        }
112	        try {
113	            return tx.execute(status -> {
114	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
115	                        .orElseThrow(() -> notFound(scheduleKey));
116	                if (plan.status() != PlanStatus.DRAFT) {
117	                    throw conflict("PLAN_STATE_CONFLICT",
118	                            "仅草稿可修改占用，当前状态: " + plan.status());
119	                }
120	                if (req.expectedVersion() != plan.version()) {
121	                    throw conflict("VERSION_CONFLICT",
122	                            "expectedVersion=" + req.expectedVersion() + " 与当前版本 " + plan.version() + " 不一致");
123	                }
124	                validateWithinOperationDay(req.occupancies(), plan.opDate());
125	                long now = System.currentTimeMillis();
126	                planRepo.replaceOccupancies(plan.id(), toOccupancies(plan.id(), req.occupancies()));
127	                planRepo.updateVersionAndStatus(plan.id(), plan.version() + 1, PlanStatus.DRAFT, now);
128	                PlanResponse response = loadPlan(scheduleKey);
129	                idemRepo.insert(OP_UPDATE, req.requestKey(), hash, toJson(response), now);
130	                return response;
131	            });
132	        } catch (DuplicateKeyException e) {
133	            return resolveDuplicate(OP_UPDATE, req.requestKey(), hash);
134	        }
135	    }
