137	    /**
138	     * 发布计划：全局发布锁内原子校验本计划列车重叠与跨计划区段重叠，
139	     * 任一冲突则整张计划保持草稿并抛出 422（携带冲突区段与计划）。
140	     */
141	    public PlanResponse publish(String scheduleKey, String requestKey) {
142	        String hash = hashAction(OP_PUBLISH, scheduleKey);
143	        Optional<PlanResponse> replay = replayIfPresent(OP_PUBLISH, requestKey, hash);
144	        if (replay.isPresent()) {
145	            return replay.get();
146	        }
147	        try {
148	            return tx.execute(status -> {
149	                planRepo.acquirePublishLock();
150	                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
151	                        .orElseThrow(() -> notFound(scheduleKey));
152	                if (plan.status() != PlanStatus.DRAFT) {
153	                    throw conflict("PLAN_STATE_CONFLICT",
154	                            "仅草稿可发布，当前状态: " + plan.status());
155	                }
156	                List<Occupancy> occupancies = planRepo.findOccupancies(plan.id());
157	                List<Map<String, Object>> conflicts = new ArrayList<>();
158	                conflicts.addAll(findTrainOverlaps(scheduleKey, occupancies));
159	                conflicts.addAll(findSectionConflicts(plan, occupancies, List.of(plan.id())));
160	                if (!conflicts.isEmpty()) {
161	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT",
162	                            "存在时隙冲突，计划保持草稿", conflicts);
163	                }
164	                long now = System.currentTimeMillis();
165	                planRepo.updateStatus(plan.id(), PlanStatus.PUBLISHED, now);
166	                PlanResponse response = loadPlan(scheduleKey);
167	                idemRepo.insert(OP_PUBLISH, requestKey, hash, toJson(response), now);
168	                return response;
169	            });
170	        } catch (DuplicateKeyException e) {
171	            return resolveDuplicate(OP_PUBLISH, requestKey, hash);
172	        }
173	    }
