278	    /**
279	     * 查询包含指定计划在内的完整有序改签链（从最前驱到最后继）；
280	     * 无改签历史的计划链中仅含自身。计划不存在返回 404。
281	     */
282	    public RescheduleChainResponse getRescheduleChain(String scheduleKey) {
283	        DayPlan plan = planRepo.findByKey(scheduleKey)
284	                .orElseThrow(() -> notFound(scheduleKey));
285	        List<DayPlan> predecessors = new ArrayList<>();
286	        DayPlan cursor = plan;
287	        while (true) {
288	            Optional<RescheduleLink> link = planRepo.findLinkBySuccessor(cursor.id());
289	            if (link.isEmpty()) {
290	                break;
291	            }
292	            cursor = planRepo.findById(link.get().predecessorPlanId())
293	                    .orElseThrow(() -> new IllegalStateException("改签链前驱缺失: " + link.get()));
294	            predecessors.add(cursor);
295	        }
296	        Collections.reverse(predecessors);
297	        List<DayPlan> chain = new ArrayList<>(predecessors);
298	        chain.add(plan);
299	        cursor = plan;
300	        while (true) {
301	            Optional<RescheduleLink> link = planRepo.findLinkByPredecessor(cursor.id());
302	            if (link.isEmpty()) {
303	                break;
304	            }
305	            cursor = planRepo.findById(link.get().successorPlanId())
306	                    .orElseThrow(() -> new IllegalStateException("改签链后继缺失: " + link.get()));
307	            chain.add(cursor);
308	        }
309	        List<RescheduleChainItem> items = chain.stream()
310	                .map(p -> new RescheduleChainItem(p.scheduleKey(), p.opDate(), p.version(),
311	                        p.status().name()))
312	                .toList();
313	        return new RescheduleChainResponse(scheduleKey, items);
314	    }
