348	    private List<Occupancy> toOccupancies(long planId, List<OccupancyRequest> requests) {
349	        List<Occupancy> result = new ArrayList<>(requests.size());
350	        for (int i = 0; i < requests.size(); i++) {
351	            OccupancyRequest r = requests.get(i);
352	            result.add(new Occupancy(0L, planId, i, r.trainNo(), r.sectionId(), r.startUtc(), r.endUtc()));
353	        }
354	        return result;
355	    }
