365	        String newKey = key("SCH");
366	        createPlan(oldKey, occ("G1", section, iso(8), iso(9)));
367	        publishPlan(oldKey, key("REQ"));
368	        // 新草稿内部列车重叠 → 首次改签 422
369	        createPlan(newKey,
370	                occ("G2", section, iso(9), iso(10)),
371	                occ("G2", section, iso(9, 30), iso(11)));
372	
373	        String requestKey = key("REQ");
374	        mvc.perform(post("/api/v1/plans/{key}/reschedule", oldKey)
375	                        .contentType(MediaType.APPLICATION_JSON)
376	                        .content(rescheduleBody(requestKey, newKey, 1, 1)))
377	                .andExpect(status().isUnprocessableEntity());
378	
379	        // 失败不占键：修正草稿（版本升至 2）后同键新参重试成功
380	        mvc.perform(put("/api/v1/plans/{key}/occupancies", newKey)
381	                        .contentType(MediaType.APPLICATION_JSON)
382	                        .content(updateBody(key("REQ"), 1, occ("G2", section, iso(9), iso(10)))))
383	                .andExpect(status().isOk());
384	        mvc.perform(post("/api/v1/plans/{key}/reschedule", oldKey)
385	                        .contentType(MediaType.APPLICATION_JSON)
386	                        .content(rescheduleBody(requestKey, newKey, 1, 2)))
387	                .andExpect(status().isOk());
388	        assertChainKeys(oldKey, oldKey, newKey);
389	    }
390	
391	    // ---------- 辅助 ----------
392	
393	    private void assertRolledBack(String oldKey, String newKey, String section) throws Exception {
394	        MvcResult oldDetail = mvc.perform(get("/api/v1/plans/{key}", oldKey))
395	                .andExpect(status().isOk()).andReturn();
396	        assertThat(read(oldDetail).get("status").asText()).isEqualTo("PUBLISHED");
397	        MvcResult newDetail = mvc.perform(get("/api/v1/plans/{key}", newKey))
398	                .andExpect(status().isOk()).andReturn();
399	        assertThat(read(newDetail).get("status").asText()).isEqualTo("DRAFT");
400	        // 未产生改签关联
401	        assertChainKeys(oldKey, oldKey);
402	        assertChainKeys(newKey, newKey);
403	    }
404	
405	    private void assertChainKeys(String queryKey, String... expectedKeys) throws Exception {
406	        MvcResult chain = mvc.perform(get("/api/v1/plans/{key}/reschedule-chain", queryKey))
407	                .andExpect(status().isOk()).andReturn();
408	        JsonNode items = read(chain).get("chain");
409	        assertThat(items).hasSize(expectedKeys.length);
410	        for (int i = 0; i < expectedKeys.length; i++) {
411	            assertThat(items.get(i).get("scheduleKey").asText()).isEqualTo(expectedKeys[i]);
412	        }
413	    }
414	
415	    private void createPlan(String scheduleKey, String... occupancies) throws Exception {
416	        mvc.perform(post("/api/v1/plans").contentType(MediaType.APPLICATION_JSON)
417	                        .content(createBody(key("REQ"), scheduleKey, occupancies)))
418	                .andExpect(status().isCreated());
419	    }
420	
421	    private void publishPlan(String scheduleKey, String requestKey) throws Exception {
422	        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
423	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(requestKey)))
424	                .andExpect(status().isOk());
425	    }
426	
427	    private void cancelPlan(String scheduleKey, String requestKey) throws Exception {
428	        mvc.perform(post("/api/v1/plans/{key}/cancel", scheduleKey)
429	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(requestKey)))
430	                .andExpect(status().isOk());
431	    }
432	
433	    private void reschedule(String oldKey, String newKey, int oldVersion, int newVersion)
434	            throws Exception {
435	        mvc.perform(post("/api/v1/plans/{key}/reschedule", oldKey)
436	                        .contentType(MediaType.APPLICATION_JSON)
437	                        .content(rescheduleBody(key("REQ"), newKey, oldVersion, newVersion)))
438	                .andExpect(status().isOk());
439	    }
440	
441	    private JsonNode read(MvcResult result) throws Exception {
442	        return objectMapper.readTree(result.getResponse().getContentAsString());
443	    }
444	
445	    private static String key(String prefix) {
446	        return prefix + "-" + UUID.randomUUID();
447	    }
448	
449	    /** 运营日当日 hour:minute（Asia/Shanghai）的 UTC 时刻。 */
450	    private static String iso(int hour, int minute) {
451	        return DAY.atTime(hour, minute).atZone(SH).toInstant().toString();
452	    }
453	
454	    /** 运营日当日 hour 点（Asia/Shanghai）的 UTC 时刻。 */
455	    private static String iso(int hour) {
456	        return iso(hour, 0);
457	    }
458	
459	    /** 运营日加 dayOffset 天后 hour 点（Asia/Shanghai）的 UTC 时刻。 */
460	    private static String iso(int hour, int minute, int dayOffset) {
461	        Instant instant = DAY.plusDays(dayOffset).atTime(hour, minute).atZone(SH).toInstant();
462	        return instant.toString();
463	    }
464	
465	    private static String occ(String train, String section, String startIso, String endIso) {
466	        return "{\"trainNo\":\"" + train + "\",\"sectionId\":\"" + section
467	                + "\",\"startUtc\":\"" + startIso + "\",\"endUtc\":\"" + endIso + "\"}";
468	    }
469	
470	    private static String createBody(String requestKey, String scheduleKey, String... occupancies) {
471	        return createBodyOnDate(requestKey, scheduleKey, DAY, occupancies);
472	    }
473	
474	    private static String createBodyOnDate(String requestKey, String scheduleKey, LocalDate opDate,
475	                                           String... occupancies) {
476	        return "{\"requestKey\":\"" + requestKey + "\",\"scheduleKey\":\"" + scheduleKey
477	                + "\",\"opDate\":\"" + opDate + "\",\"occupancies\":[" + String.join(",", occupancies)
478	                + "]}";
479	    }
480	
481	    private static String updateBody(String requestKey, int expectedVersion, String... occupancies) {
482	        return "{\"requestKey\":\"" + requestKey + "\",\"expectedVersion\":" + expectedVersion
483	                + ",\"occupancies\":[" + String.join(",", occupancies) + "]}";
484	    }
485	
486	    private static String actionBody(String requestKey) {
487	        return "{\"requestKey\":\"" + requestKey + "\"}";
488	    }
489	
490	    private static String rescheduleBody(String requestKey, String newScheduleKey,
491	                                         int expectedOldVersion, int expectedNewVersion) {
492	        return "{\"requestKey\":\"" + requestKey + "\",\"newScheduleKey\":\"" + newScheduleKey
493	                + "\",\"expectedOldVersion\":" + expectedOldVersion
494	                + ",\"expectedNewVersion\":" + expectedNewVersion + "}";
495	    }
496	}
