    Set<String> sections = occupancies sectionIds;
    List<WeatherRestriction> active = restrictionRepo.findActiveOverlapping(sections, minStart, maxEnd);
    if (active.isEmpty()) return Optional.empty();
    List<SegmentImpact> impacts = new ArrayList<>();
    for (Occupancy o : occupancies) {
        List<WeatherRestriction> hits = active.stream().filter(r -> r.sectionId().equals(o.sectionId()) && overlap).toList();
        if (!hits.isEmpty()) {
            impacts.add(new SegmentImpact(o, unionOverlapMinutes(o, hits), binding(hits)));
        }
    }
    if (impacts.isEmpty()) return Optional.empty();
    // 已开始运行的计划不可重排
    Instant now = clock.instant();
    if (!minStart.isAfter(now)) {
        throw 422 REARRANGE_NOT_ALLOWED with details {scheduleKey, firstStartUtc, nowUtc}
    }
    long minInterval = occupancies.stream().mapToLong(o -> max(1, duration.toMinutes())).min();
    LocalDate opDate = plan.opDate();
    Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
    for (long k = 1; ; k++) {
